#include <iostream>
#include <vector>
#include <queue>
#include <cstring>
using namespace std;

const int INF = 0x3f3f3f3f;
const int MAXN = 20;
const int MAXV = 2 * MAXN * MAXN;

char mazeX[MAXN][MAXN], mazeY[MAXN][MAXN];
int distMap[MAXN][MAXN];
int n, t;

int deltaX[] = {1, 0, -1, 0};
int deltaY[] = {0, 1, 0, -1};

void run_bfs_search(int startX, int startY) {
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            distMap[i][j] = INF;
    distMap[startX][startY] = 0;
    queue<pair<int, int>> q;
    q.push({startX, startY});
    while (!q.empty()) {
        auto [x, y] = q.front(); q.pop();
        for (int dir = 0; dir < 4; ++dir) {
            int nx = x + deltaX[dir], ny = y + deltaY[dir];
            if (nx >= n || ny >= n || nx < 0 || ny < 0) continue;
            if ('0' <= mazeX[nx][ny] && mazeX[nx][ny] <= '9' && distMap[nx][ny] == INF) {
                distMap[nx][ny] = distMap[x][y] + 1;
                q.push({nx, ny});
            }
        }
    }
}

vector<int> network[MAXV];
int flowCap[MAXV][MAXV];

void addLink(int u, int v, int c) {
    network[u].push_back(v);
    network[v].push_back(u);
    flowCap[u][v] = c;
    flowCap[v][u] = 0;
}

int timeGrid[MAXN][MAXN];
bool visitedNodes[MAXV];
int levelNodes[MAXV];

bool build_bfs_levels(int s, int t) {
    memset(levelNodes, -1, sizeof(levelNodes));
    levelNodes[s] = 0;
    queue<int> q;
    q.push(s);
    while (!q.empty() && levelNodes[t] == -1) {
        int v = q.front(); q.pop();
        for (auto &nxt : network[v]) {
            if (!flowCap[v][nxt] || levelNodes[nxt] != -1) continue;
            levelNodes[nxt] = levelNodes[v] + 1;
            q.push(nxt);
        }
    }
    return levelNodes[t] != -1;
}

void explore_bfs_final(int px, int py) {
    memset(timeGrid, INF, sizeof(timeGrid));
    timeGrid[px][py] = 0;
    if ('1' <= mazeY[px][py] && mazeY[px][py] <= '9')
        addLink(n * px + py, n * n + n * px + py, INF);
    queue<pair<int, int>> q;
    q.push({px, py});
    while (!q.empty()) {
        auto [x, y] = q.front(); q.pop();
        for (int d = 0; d < 4; ++d) {
            int nx = x + deltaX[d], ny = y + deltaY[d];
            if (nx >= n || ny >= n || nx < 0 || ny < 0) continue;
            if (timeGrid[nx][ny] != INF) continue;
            if (!('0' <= mazeX[nx][ny] && mazeX[nx][ny] <= '9')) continue;
            if (timeGrid[x][y] + 1 <= min(distMap[nx][ny] - 1, t)) {
                timeGrid[nx][ny] = timeGrid[x][y] + 1;
                q.push({nx, ny});
            }
            if (timeGrid[x][y] + 1 <= min(distMap[nx][ny], t) && '1' <= mazeY[nx][ny] && mazeY[nx][ny] <= '9')
                addLink(n * px + py, n * n + n * nx + ny, INF);
        }
    }
}

int dfs_max_flow(int v, int t, int f) {
    if (v == t) return f;
    visitedNodes[v] = true;
    for (auto &nxt : network[v]) {
        if (!flowCap[v][nxt] || visitedNodes[nxt] || levelNodes[nxt] != levelNodes[v] + 1) continue;
        int pushed = dfs_max_flow(nxt, t, min(f, flowCap[v][nxt]));
        if (pushed) {
            flowCap[v][nxt] -= pushed;
            flowCap[nxt][v] += pushed;
            return pushed;
        }
    }
    return 0;
}

int compute_max_flow_final(int s, int t) {
    int total = 0, flow;
    while (build_bfs_levels(s, t)) {
        memset(visitedNodes, 0, sizeof(visitedNodes));
        while ((flow = dfs_max_flow(s, t, INF)) > 0) {
            total += flow;
            memset(visitedNodes, 0, sizeof(visitedNodes));
        }
    }
    return total;
}

int main() {
    cin >> n >> t;
    int startX, startY;
    int s_node = MAXV - 2, t_node = MAXV - 1;
    for (int a = 0; a < n; ++a) {
        for (int b = 0; b < n; ++b) {
            cin >> mazeX[a][b];
            if (mazeX[a][b] == 'Z') {
                startX = a; startY = b;
            } else if ('1' <= mazeX[a][b] && mazeX[a][b] <= '9') {
