import java.util.*;
import java.io.*;

public class MazeFlow {
    static final int INF = 0x3f3f3f3f;
    static final int MAXN = 20;
    static final int MAXV = 2 * MAXN * MAXN;

    static char[][] mazeX = new char[MAXN][MAXN];
    static char[][] mazeY = new char[MAXN][MAXN];
    static int[][] distMap = new int[MAXN][MAXN];
    static int n, t;

    static int[] deltaX = {1, 0, -1, 0};
    static int[] deltaY = {0, 1, 0, -1};

    static List<Integer>[] network = new ArrayList[MAXV];
    static int[][] flowCap = new int[MAXV][MAXV];

    static int[] timeGrid = new int[MAXN][MAXN];
    static boolean[] visitedNodes = new boolean[MAXV];
    static int[] levelNodes = new int[MAXV];

    static {
        for (int i = 0; i < MAXV; i++) {
            network[i] = new ArrayList<>();
        }
    }

    static void run_bfs_search(int startX, int startY) {
        for (int i = 0; i < n; ++i)
            for (int j = 0; j < n; ++j)
                distMap[i][j] = INF;
        distMap[startX][startY] = 0;
        Queue<int[]> q = new LinkedList<>();
        q.offer(new int[]{startX, startY});
        while (!q.isEmpty()) {
            int[] front = q.poll();
            int x = front[0], y = front[1];
            for (int dir = 0; dir < 4; ++dir) {
                int nx = x + deltaX[dir], ny = y + deltaY[dir];
                if (nx >= n || ny >= n || nx < 0 || ny < 0) continue;
                if ('0' <= mazeX[nx][ny] && mazeX[nx][ny] <= '9' && distMap[nx][ny] == INF) {
                    distMap[nx][ny] = distMap[x][y] + 1;
                    q.offer(new int[]{nx, ny});
                }
            }
        }
    }

    static void addLink(int u, int v, int c) {
        network[u].add(v);
        network[v].add(u);
        flowCap[u][v] = c;
        flowCap[v][u] = 0;
    }

    static boolean build_bfs_levels(int s, int t) {
        Arrays.fill(levelNodes, -1);
        levelNodes[s] = 0;
        Queue<Integer> q = new LinkedList<>();
        q.offer(s);
        while (!q.isEmpty() && levelNodes[t] == -1) {
            int v = q.poll();
            for (int nxt : network[v]) {
                if (flowCap[v][nxt] == 0 || levelNodes[nxt] != -1) continue;
                levelNodes[nxt] = levelNodes[v] + 1;
                q.offer(nxt);
            }
        }
        return levelNodes[t] != -1;
    }

    static void explore_bfs_final(int px, int py) {
        for (int i = 0; i < MAXN; ++i)
            Arrays.fill(timeGrid[i], INF);
        timeGrid[px][py] = 0;
        if ('1' <= mazeY[px][py] && mazeY[px][py] <= '9')
            addLink(n * px + py, n * n + n * px + py, INF);
        Queue<int[]> q = new LinkedList<>();
        q.offer(new int[]{px, py});
        while (!q.isEmpty()) {
            int[] front = q.poll();
            int x = front[0], y = front[1];
            for (int d = 0; d < 4; ++d) {
                int nx = x + deltaX[d], ny = y + deltaY[d];
                if (nx >= n || ny >= n || nx < 0 || ny < 0) continue;
                if (timeGrid[nx][ny] != INF) continue;
                if (!('0' <= mazeX[nx][ny] && mazeX[nx][ny] <= '9')) continue;
                if (timeGrid[x][y] + 1 <= Math.min(distMap[nx][ny] - 1, t)) {
                    timeGrid[nx][ny] = timeGrid[x][y] + 1;
                    q.offer(new int[]{nx, ny});
                }
                if (timeGrid[x][y] + 1 <= Math.min(distMap[nx][ny], t) && '1' <= mazeY[nx][ny] && mazeY[nx][ny] <= '9')
                    addLink(n * px + py, n * n + n * nx + ny, INF);
            }
        }
    }

    static int dfs_max_flow(int v, int t, int f) {
        if (v == t) return f;
        visitedNodes[v] = true;
        for (int nxt : network[v]) {
            if (flowCap[v][nxt] == 0 || visitedNodes[nxt] || levelNodes[nxt] != levelNodes[v] + 1) continue;
            int pushed = dfs_max_flow(nxt, t, Math.min(f, flowCap[v][nxt]));
            if (pushed > 0) {
                flowCap[v][nxt] -= pushed;
                flowCap[nxt][v] += pushed;
                return pushed;
            }
        }
        return 0;
    }

    static int compute_max_flow_final(int s, int t) {
        int total = 0, flow;
        while (build_bfs_levels(s, t)) {
            Arrays.fill(visitedNodes, false);
            while ((flow = dfs_max_flow(s, t, INF)) > 0) {
                total += flow;
                Arrays.fill(visitedNodes, false);
            }
        }
        return total;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        t = Integer.parseInt(st.nextToken());
        int s_node = MAXV - 2;
        int t_node = MAXV - 1;
        int startX = -1, startY = -1;

        for (int a = 0; a < n; ++a) {
            String line = br.readLine();
            for (int b = 0; b < n; ++b) {
                mazeX[a][b] = line.charAt(b);
                if (mazeX[a][b] == 'Z') {
                    startX = a;
                    startY = b;
                } else if ('1' <= mazeX[a][b] && mazeX[a][b] <= '9') {
                    addLink(s_node, a * n + b, mazeX[a][b] - '0');
                }
            }
        }
        run_bfs_search(startX, startY);
        for (int a = 0; a < n; ++a) {
            String line = br.readLine();
            for (int b = 0; b < n; ++b) {
                mazeY[a][b] = line.charAt(b);
                if ('1' <= mazeY[a][b] && mazeY[a][b] <= '9') {
                    addLink(n * n + a * n + b, t_node, mazeY[a][b] - '0');
                }
            }
        }
        for (int a = 0; a < n; ++a) {
            for (int b = 0; b < n; ++b) {
                if ('1' <= mazeX[a][b] && mazeX[a][b] <= '9') {
                    explore_bfs_final(a, b);
                }
            }
        }
        System.out.println(compute_max_flow_final(s_node, t_node));
    }
}
